      .card { border: 1px solid #d9deea; border-radius: 0.75rem; padding: 1.25rem; background: #fbfcff; }
      code { background: #eef1f8; padding: 0.15rem 0.35rem; border-radius: 0.25rem; }
    </style>
  </head>
  <body>
    <main>${body}</main>
  </body>
</html>`;
